export const getFormatName = (name, separator = '', replace = '') => {
    const _name = getProperName(name);
    if (!!separator && replace === '') {
        return name
            ?.split(separator)
            .map((element) => getProperName(element))
            .toString()
            .replaceAll(',', '');
    }
    return !!separator && !!replace
        ? _name.replaceAll(separator, replace)
        : _name;
};
