const getSubList = (list, elementName, template = '') => {
    const result = typeof list[0] === 'string'
        ? !!template
            ? list.map((element) => template.replaceAll('[__]', element))
            : list
        : list.map((element) => {
            const _element = element;
            if (elementName === 'element') {
                return !!template
                    ? template.replaceAll('[__]', _element.element)
                    : _element.element;
            }
            else if (elementName === 'name') {
                return !!template
                    ? template.replaceAll('[__]', _element.name)
                    : _element.name;
            }
            else {
                throw new Error(`Invalid elementName: ${elementName}`);
            }
        });
    return result || [];
};
const getMergeList = (list, definition, splitChar) => {
    const styles = definition?.split(splitChar);
    const mergeList = list.map((element, index) => element.concat(': var(--', styles[index]?.trim(), ');'));
    return mergeList.toString().replaceAll(',', ' ');
};
