export const getSandboxConsiderationsDocumentation = (element, introductionContent = '', content = '', isWarning = false, implementationDetails = [], style = '', isClassNameVar = false, isInherit = false, isOmitImportant = false) => {
    let _implementationDetails = '';
    if (!!implementationDetails.length) {
        const splitChar = '|||';
        const patternToReplaceOneLine = /(and )|(\, )/g;
        const elementList = getSubList(implementationDetails, 'element');
        const varList = getSubList(implementationDetails, 'name');
        const definition = getListingOnOneLine(elementList, '`--bmb_[__]-{[__]}`');
        const definitionClass = definition.replaceAll('--', '');
        const _definition = getListingOnOneLine(varList, '`--bmb_[__]-4`');
        const definitionVar = _definition.replaceAll('_', '-');
        const size = getListingOnOneLine(elementList, '{[__]}');
        const variableDescription = `the ${definitionVar.replaceAll('-4', '')} variable${varList.length > 1 ? 's' : ''}`;
        const list = getListingOnOneLine(elementList);
        const _classes = getSubList(implementationDetails, 'element', 'bmb_[__]-4');
        const classes = _classes.toLocaleString().replaceAll(',', ' ');
        const variableInheritStyles = `${style.concat(!!style ? ' ' : '', getMergeList(varList, definitionVar
            .replace(patternToReplaceOneLine, splitChar)
            .replace(/\`|(--)|(-4)/g, ''), splitChar))}`;
        const variableStyles = `${style.concat(!!style ? ' ' : '', getMergeList(varList, classes.replaceAll('_', '-').replaceAll(' ', splitChar), splitChar))}`;
        _implementationDetails = `
>
### Class Name
>${getVariableDetail(element, classes, list, definitionClass, size, style, isInherit, variableDescription, variableInheritStyles)}
><br/>
### CSS Variable
>${getVariableDetail(element, '', list, definition.replaceAll('_', '-'), size, variableStyles)}
><br/>
    `;
    }
    return `
${isOmitImportant ? '' : getReferenceRecommendationForVariable(element)}
${!isOmitImportant && isWarning ? '<br/>' : ''}
${isWarning
        ? getAlertBlockquote(`You should be careful when using ${element}, as they can affect ${DESIGN_SYSTEM_TITLE} components. Some components may override this attribute, so check the component's documentation before applying the ${element} class.<br/>`, {
            title: '###'.concat(RELEVANT_TITLE.warning),
            blockquoteType: BlockquoteType.warning,
        })
        : ''}
>${introductionContent}
>${!!implementationDetails.length
        ? `The ${element} is defined in the CSS variables and can be used in the application by using ${isClassNameVar ? 'the class name or ' : ''}the CSS variable name.
><br/><br/>`
        : ''}
>${_implementationDetails}
>${content}
>### ${SANDBOX_TITLE}
>${getHelpDescriptionForGeneratingVariables(element)}:
`;
};
